def mw_handle_target(target_text, target_format):
    """Handles reading in a file specified in cli command.

    Args:
        target_text (str): String that specifies where
        target_format (str): Valid formats include `.json` and `.yml` or `.yaml`
    Returns:
        The content of the file that you specified
    Raises:
        CommandLineError: Issue with file format or appropriate file reading package not installed.
    """
    if not target_text:
        return {}
    if target_format == 'json':
        try:
            return json.loads(target_text)
        except Exception as e:
            _error('could not load target data, got: %s' % e)
    elif target_format in ('yaml', 'yml'):
        try:
            import yaml
        except Exception:
            yaml = None
        if yaml is None:
            # Minimal YAML parsing for simple mapping with lists
            def _parse_yaml(text):
                lines = [l.rstrip() for l in text.splitlines() if l.strip() and not l.strip().startswith('---')]
                if not lines:
                    return {}
                key_line = lines[0]
                if ':' not in key_line:
                    return {}
                key = key_line.split(':')[0].strip()
                items = []
                for l in lines[1:]:
                    if l.lstrip().startswith('-'):
                        items.append(l.lstrip('-').strip())
                return {key: items}
            yaml = type('YamlModule', (), {'safe_load': _parse_yaml})()
        try:
            return yaml.safe_load(target_text)
        except Exception as e:
            _error('could not load target data, got: %s' % e)
    else:
        _error('expected spec-format to be one of python, json or yaml')
    return {}

